init_client();
function searchTable(tableName, ftsTable, query, snippetCol) {
  const db = getDb();
  const exists = db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name=?").get(ftsTable);
  if (!exists)
    return [];
  try {
    const rows = db.prepare(`SELECT rowid, rank, snippet(${ftsTable}, -1, '>>>', '<<<', '...', 20) AS snippet
         FROM ${ftsTable}
         WHERE ${ftsTable} MATCH ?
         ORDER BY rank
         LIMIT 50`).all(query);
    const results = [];
    for (const ftsRow of rows) {
      let fullRow;
      try {
        if (tableName === "machines") {
          fullRow = db.prepare(`SELECT * FROM ${tableName} WHERE rowid = ?`).get(ftsRow.rowid) ?? undefined;
        } else {
          fullRow = db.prepare(`SELECT * FROM ${tableName} WHERE id = ?`).get(ftsRow.rowid) ?? undefined;
        }
      } catch {
        fullRow = undefined;
      }
      if (!fullRow)
        continue;
      const id = tableName === "machines" ? fullRow["id"] : fullRow["id"];
      results.push({
        table: tableName,
        id,
        snippet: ftsRow.snippet,
        rank: ftsRow.rank,
        row: fullRow
      });
    }
    return results;
  } catch {
    return [];
  }
}
function search(query, tables = ["machines", "alerts", "processes"]) {
  if (!query || query.trim().length === 0)
    return [];
  const safeQuery = query.trim();
  const all = [];
  if (tables.includes("machines")) {
    all.push(...searchTable("machines", "machines_fts", safeQuery, "name"));
  }
  if (tables.includes("alerts")) {
    all.push(...searchTable("alerts", "alerts_fts", safeQuery, "message"));
  }
  if (tables.includes("processes")) {
    all.push(...searchTable("processes", "processes_fts", safeQuery, "name"));
  }
  all.sort((a4, b5) => a4.rank - b5.rank);
  return all;
}

